package org.kanger;
import java.util.*;
import org.kanger.exception.*;
import org.kanger.enums.StorageLifecycleErrorCode;

public final class ContextDependentFamilyOutcomeRunner {
    private static int checks;
    private static void need(boolean yes,String why){checks++;if(!yes)throw new AssertionError(why);}
    private static Mind memory(String text)throws Exception{User u=new User();Mind m=new Mind(u);u.setCurrentMind(m);need(m.compile(text,null,false),"outcome fixture");return m;}
    private static ContextDependentSymbolicCacheSnapshot.Snapshot snapshot(Mind m,UUID id,boolean local)throws Exception{ContextDependentSymbolicCacheSnapshot.Result result=ContextDependentSymbolicCacheSnapshot.capture(m,ContextProductionInventory.inspect(m,id,1,local,Collections.emptyList(),1000));need(result.snapshot!=null,"outcome snapshot");return result.snapshot;}
    private static void run(boolean conflict)throws Exception{
        UUID xid=UUID.fromString("11111111-1111-1111-1111-111111111111"),aid=UUID.fromString("22222222-2222-2222-2222-222222222222");Mind x=memory(conflict?"!@u ~tail(u);":"!marker(9);"),a=memory("!$u rel(1,u,1); !@u rel(1,u,1)->middle(u); !@u middle(u)->tail(u);");ContextDependentSymbolicCacheSnapshot.Snapshot xs=snapshot(x,xid,true),as=snapshot(a,aid,false);
        Map<UUID,String> names=new HashMap<>();names.put(xid,"Source");names.put(aid,"Rules");Map<UUID,ContextProductionInventory> inventories=new HashMap<>();inventories.put(xid,xs.inventory);inventories.put(aid,as.inventory);String before=DmzObservationStateFingerprint.capture(a);
        ContextDependentModelSearchInspection.Result model=ContextDependentSymbolicFamilyInspection.inspect(x,xs,Collections.singletonList(new ContextDependentSymbolicFamilyInspection.Member(a,as)));
        if(conflict){boolean refused=false;try{ContextDependentFamilyOutcome.requireModelled(model,names,inventories);}catch(ContextDependentFamilyCommitException error){refused=error.getErrorCode()==StorageLifecycleErrorCode.STORAGE_CONTEXT_CONFLICT&&!error.getCollisions().isEmpty()&&error.getFamilyResult()==model;StringBuilder text=new StringBuilder(error.toString());for(ContextQualification.CollisionWitness proof:error.getCollisions())text.append(proof.getLeft()).append(proof.getRight());need(text.toString().contains("Source@1#")&&text.toString().contains("Rules@1#")&&!text.toString().contains(xid.toString())&&!text.toString().contains(aid.toString()),"human conflict evidence uses context names and actual original rules");}need(refused,"only a real sourced family refutation becomes a conflict");
            boolean incomplete=false;try{ContextDependentFamilyOutcome.requireModelled(model,Collections.singletonMap(xid,"Source"),inventories);}catch(StorageLifecycleException error){incomplete=error.getErrorCode()==StorageLifecycleErrorCode.STORAGE_CONTEXT_INCOMPLETE&&error.getCollisions().isEmpty();}need(incomplete,"missing named evidence never fabricates conflict witnesses");
        }else{ContextDependentFamilyOutcome.requireModelled(model,names,inventories);need(model.status==ContextDependentModelSearchInspection.Status.MODELLED_PENDING,"current complete model passes precondition only");
            ContextDependentCutInspection.Member root=new ContextDependentCutInspection.Member(x,xs.diagnosticPrimaryView(x)),member=new ContextDependentCutInspection.Member(a,as.diagnosticPrimaryView(a));
            ContextDependentModelSearchInspection.Result limited=ContextDependentAutomaticInspection.inspect(root,Collections.singletonList(new ContextDependentCutInspection.Cut(null,Collections.singletonList(member))),new ContextDependentIterationInspection.Request(new ContextDependentReplayInspection.Policy(2000000,1000,1000,64000000,200000),10000,8),new ContextDependentModelSearchInspection.Limits(30,100000,100000,1,64000000,64000000,64000000,64000000,64000000),new ContextDependentRuntimeContinuationInspection.Projection(100000,1000000,64000000,64000000,64000000,64000000));
            need(limited.status==ContextDependentModelSearchInspection.Status.INCOMPLETE,"actual candidate limit provides a real incomplete result");boolean incomplete=false;try{ContextDependentFamilyOutcome.requireModelled(limited,names,inventories);}catch(StorageLifecycleException error){incomplete=error.getErrorCode()==StorageLifecycleErrorCode.STORAGE_CONTEXT_INCOMPLETE&&error.getCollisions().isEmpty();}need(incomplete,"exhausted model budget is incomplete, never a theory conflict");
            boolean manifest=false;try{ContextDependentFamilyOutcome.requireModelled(model,names,Collections.singletonMap(xid,xs.inventory));}catch(StorageLifecycleException error){manifest=error.getErrorCode()==StorageLifecycleErrorCode.STORAGE_CONTEXT_INCOMPLETE;}need(manifest,"incomplete family manifest cannot pass a complete-model precondition");
        }
        need(before.equals(DmzObservationStateFingerprint.capture(a)),"outcome handling never changes native witness or cache");need(ContextDependentFamilyOutcome.readable("context:"+aid+" unknown:"+UUID.fromString("33333333-3333-3333-3333-333333333333"),names).equals("context:Rules unknown:<unknown context>"),"known and unknown UUID diagnostics remain readable without identifier leakage");
    }
    public static void main(String[] args)throws Exception{System.setProperty("user.home",java.nio.file.Files.createTempDirectory("symbolic-family-outcome-").toString());run(false);run(true);System.out.println("CONTEXT_DEPENDENT_FAMILY_OUTCOME_PASS checks="+checks);}
}
